<?php
declare(strict_types=1); namespace App\Controllers;
use App\Core\Auth;use App\Core\Controller;use App\Core\Flash;use App\Models\User;use PDO;
final class AdminController extends Controller { public function __construct(private readonly Auth $auth,private readonly User $users,private readonly PDO $pdo){} public function index():void{$this->auth->requireAdmin();$summary=[];foreach(['users','exercises','diary_entries','money_records','habits']as$table)$summary[$table]=(int)$this->pdo->query("SELECT COUNT(*) FROM {$table}")->fetchColumn();$summary['students']=(int)$this->pdo->query("SELECT COUNT(*) FROM users WHERE role='Student'")->fetchColumn();$this->view('admin/index',['pageTitle'=>'Administration','users'=>$this->users->all(),'summary'=>$summary]);} public function createForm():void{$this->auth->requireAdmin();$this->view('admin/user_form',['pageTitle'=>'Add User','user'=>null,'errors'=>[]]);} public function store():void{$this->requirePost();$this->requireCsrf();$this->auth->requireAdmin();$data=$this->valid($_POST,true);if($data['errors']){$this->view('admin/user_form',['pageTitle'=>'Add User','user'=>$_POST,'errors'=>$data['errors']]);return;}$this->users->create($data['username'],$data['email'],$data['password'],$data['full_name'],$data['role']);Flash::add('success','User created.');$this->redirect('admin');} public function editForm():void{$this->auth->requireAdmin();$user=$this->users->findById((int)($_GET['id']??0));if(!$user){Flash::add('error','User not found.');$this->redirect('admin');}$this->view('admin/user_form',['pageTitle'=>'Edit User','user'=>$user,'errors'=>[]]);} public function update():void{$this->requirePost();$this->requireCsrf();$this->auth->requireAdmin();$id=(int)($_POST['user_id']??0);$existing=$this->users->findById($id);if(!$existing){Flash::add('error','User not found.');$this->redirect('admin');}$data=$this->valid($_POST,false,$id);if($data['errors']){$_POST['user_id']=$id;$this->view('admin/user_form',['pageTitle'=>'Edit User','user'=>$_POST,'errors'=>$data['errors']]);return;}$this->users->updateProfile($id,$data['full_name'],$data['username'],$data['email']);$this->users->updateRole($id,$data['role']);if($data['password']!=='')$this->users->updatePassword($id,$data['password']);Flash::add('success','User updated.');$this->redirect('admin');} public function delete():void{$this->requirePost();$this->requireCsrf();$this->auth->requireAdmin();$id=(int)($_POST['user_id']??0);if($id===$this->auth->id()){Flash::add('error','You cannot delete your own account.');}elseif($this->users->delete($id))Flash::add('success','User deleted.');else Flash::add('error','User not found.');$this->redirect('admin');} private function valid(array $in,bool $passwordRequired,?int $except=null):array{$d=['full_name'=>trim((string)($in['full_name']??'')),'username'=>trim((string)($in['username']??'')),'email'=>trim((string)($in['email']??'')),'role'=>(string)($in['role']??'Student'),'password'=>(string)($in['password']??'')];$e=[];if($d['full_name']===''||mb_strlen($d['full_name'])>100)$e[]='Full name is required and must be 100 characters or fewer.';if(!preg_match('/^[A-Za-z0-9_]{4,30}$/',$d['username']))$e[]='Username must be 4-30 letters, numbers, or underscores.';if(!filter_var($d['email'],FILTER_VALIDATE_EMAIL))$e[]='Enter a valid email address.';if(!in_array($d['role'],['Student','Admin'],true))$e[]='Choose a valid role.';if(($passwordRequired&&strlen($d['password'])<6)||(!$passwordRequired&&$d['password']!==''&&strlen($d['password'])<6))$e[]='Password must be at least 6 characters.';if(!$e&&$this->users->usernameOrEmailExists($d['username'],$d['email'],$except))$e[]='That username or email is already registered.';return$d+['errors'=>$e];} }
